/* Splitter / linesiter state. Classes are declared `is native`
   with no user fields; the runtime supplies the real layout,
   stack-allocated value type (48 bytes). Both iterators share
   the same struct — linesiter leaves sep NULL. */
typedef struct {
    const char* src;
    uint64_t    src_len;
    const char* sep;
    uint64_t    sep_len;
    uint64_t    cursor;
    bool        done;
} z_t3896_t;

typedef z_t3896_t z_t3899_t;


static z_t3896_t z_t106_split(
    const z_t106_t* self, const z_t106_t* sep);
static z_t3896_t z_t106_split(
    const z_t106_t* self, const z_t106_t* sep) {
    z_t3896_t s;
    s.src = self->data;
    s.src_len = self->length;
    s.sep = sep->data;
    s.sep_len = sep->length;
    s.cursor = 0;
    s.done = (sep->length == 0);
    return s;
}


static z_t846_t z_t3896_call(z_t3896_t* s);
static z_t846_t z_t3896_call(z_t3896_t* s) {
    z_t846_t out = {0};
    if (s->done) {
        out.tag = Z_OPTION_STRINGVIEW_TAG_NONE;
        return out;
    }
    const char* start = s->src + s->cursor;
    uint64_t remaining = s->src_len - s->cursor;
    if (s->sep_len > remaining) {
        /* no more separators possible — return the tail */
        z_t106_t* boxed = (z_t106_t*)z_xmalloc(sizeof(z_t106_t));
        boxed->data = start;
        boxed->length = remaining;
        s->cursor = s->src_len;
        s->done = true;
        out.tag = Z_OPTION_STRINGVIEW_TAG_SOME;
        out.data = boxed;
        return out;
    }
    uint64_t scan_end = remaining - s->sep_len;
    for (uint64_t i = 0; i <= scan_end; i++) {
        if (memcmp(start + i, s->sep, s->sep_len) == 0) {
            z_t106_t* boxed = (z_t106_t*)z_xmalloc(sizeof(z_t106_t));
            boxed->data = start;
            boxed->length = i;
            s->cursor += i + s->sep_len;
            out.tag = Z_OPTION_STRINGVIEW_TAG_SOME;
            out.data = boxed;
            return out;
        }
    }
    /* no separator in remaining — final fragment */
    z_t106_t* boxed = (z_t106_t*)z_xmalloc(sizeof(z_t106_t));
    boxed->data = start;
    boxed->length = remaining;
    s->cursor = s->src_len;
    s->done = true;
    out.tag = Z_OPTION_STRINGVIEW_TAG_SOME;
    out.data = boxed;
    return out;
}


static z_t3899_t z_t106_lines(const z_t106_t* self);
static z_t3899_t z_t106_lines(const z_t106_t* self) {
    z_t3899_t s;
    s.src = self->data;
    s.src_len = self->length;
    s.sep = NULL;
    s.sep_len = 0;
    s.cursor = 0;
    s.done = (self->length == 0);
    return s;
}


static z_t846_t z_t3899_call(z_t3899_t* s);
static z_t846_t z_t3899_call(z_t3899_t* s) {
    z_t846_t out = {0};
    if (s->done) {
        out.tag = Z_OPTION_STRINGVIEW_TAG_NONE;
        return out;
    }
    const char* start = s->src + s->cursor;
    uint64_t remaining = s->src_len - s->cursor;
    uint64_t i = 0;
    while (i < remaining && start[i] != '\n') i++;
    uint64_t line_len = i;
    if (line_len > 0 && start[line_len - 1] == '\r') line_len--;
    z_t106_t* boxed = (z_t106_t*)z_xmalloc(sizeof(z_t106_t));
    boxed->data = start;
    boxed->length = line_len;
    if (i == remaining) {
        s->cursor = s->src_len;
        s->done = true;
    } else {
        s->cursor += i + 1;
        if (s->cursor >= s->src_len) s->done = true;
    }
    out.tag = Z_OPTION_STRINGVIEW_TAG_SOME;
    out.data = boxed;
    return out;
}


/* string_join -- borrow `parts` (read-only) and return a new
   owned string. `parts` is pointer-passed (Phase A default for
   stack-reftype params); caller retains ownership. */
static z_t75_t z_stringJoin(
    z_t1098_t* parts, z_t106_t sep);
static z_t75_t z_stringJoin(
    z_t1098_t* parts, z_t106_t sep) {
    z_t75_t out = {0};
    uint64_t n = parts->length;
    if (n == 0) {
        out.capacity = 1;
        out.data = (char*)z_xmalloc(1);
        out.data[0] = '\0';
        return out;
    }
    uint64_t total = sep.length * (n - 1);
    for (uint64_t i = 0; i < n; i++) {
        total += parts->data[i].size;
    }
    out.size = total;
    out.capacity = total + 1;
    out.data = (char*)z_xmalloc(out.capacity + 1);
    uint64_t pos = 0;
    for (uint64_t i = 0; i < n; i++) {
        if (i > 0 && sep.length > 0) {
            memcpy(out.data + pos, sep.data, sep.length);
            pos += sep.length;
        }
        memcpy(out.data + pos, parts->data[i].data, parts->data[i].size);
        pos += parts->data[i].size;
    }
    out.data[total] = '\0';
    return out;
}


static bool z_t106_startsWith(const z_t106_t* self, const z_t106_t* prefix);
static bool z_t106_startsWith(const z_t106_t* self, const z_t106_t* prefix) {
    if (prefix->length > self->length) return false;
    if (prefix->length == 0) return true;
    return memcmp(self->data, prefix->data, prefix->length) == 0;
}

static bool z_t106_endsWith(const z_t106_t* self, const z_t106_t* suffix);
static bool z_t106_endsWith(const z_t106_t* self, const z_t106_t* suffix) {
    if (suffix->length > self->length) return false;
    if (suffix->length == 0) return true;
    return memcmp(self->data + (self->length - suffix->length),
                  suffix->data, suffix->length) == 0;
}

static uint64_t z_t106_indexOf_raw(const z_t106_t* self, const z_t106_t* needle);
static uint64_t z_t106_indexOf_raw(const z_t106_t* self, const z_t106_t* needle) {
    if (needle->length == 0) return 0;
    if (needle->length > self->length) return UINT64_MAX;
    uint64_t last = self->length - needle->length;
    for (uint64_t i = 0; i <= last; i++) {
        if (memcmp(self->data + i, needle->data, needle->length) == 0) {
            return i;
        }
    }
    return UINT64_MAX;
}


static bool z_t106_contains(const z_t106_t* self, const z_t106_t* needle);
static bool z_t106_contains(const z_t106_t* self, const z_t106_t* needle) {
    return z_t106_indexOf_raw(self, needle) != UINT64_MAX;
}

static bool z_ascii_is_ws(unsigned char c);
static bool z_ascii_is_ws(unsigned char c) {
    return c == ' ' || c == '\t' || c == '\n'
        || c == '\v' || c == '\f' || c == '\r';
}

static z_t106_t z_t106_substring(const z_t106_t* self, uint64_t from, uint64_t to);
static z_t106_t z_t106_substring(const z_t106_t* self, uint64_t from, uint64_t to) {
    if (from > self->length || to > self->length || from > to) z_panic("substring: bounds error");
    return (z_t106_t){ self->data + from, to - from };
}
static uint64_t z_t106_hash(const z_t106_t* self);
static uint64_t z_t106_hash(const z_t106_t* self) {
    return z_siphash_stringview(*self);
}
static z_t106_t z_t106_trim(const z_t106_t* self);
static z_t106_t z_t106_trim(const z_t106_t* self) {
    const char* p = self->data;
    const char* end = self->data + self->length;
    while (p < end && z_ascii_is_ws((unsigned char)*p)) p++;
    while (end > p && z_ascii_is_ws((unsigned char)end[-1])) end--;
    z_t106_t out = { p, (uint64_t)(end - p) };
    return out;
}

static z_t75_t z_t106_replace_impl(
    const z_t106_t* self, const z_t106_t* needle,
    const z_t106_t* repl, bool once);
static z_t75_t z_t106_replace_impl(
    const z_t106_t* self, const z_t106_t* needle,
    const z_t106_t* repl, bool once) {
    /* empty needle: just copy self */
    if (needle->length == 0) {
        z_t75_t z = {0};
        z.size = self->length;
        z.capacity = self->length + 1;
        z.data = (char*)z_xmalloc(z.capacity + 1);
        memcpy(z.data, self->data, self->length);
        z.data[self->length] = '\0';
        return z;
    }
    /* pass 1: count matches so we can size the output once */
    uint64_t matches = 0;
    if (needle->length <= self->length) {
        uint64_t last = self->length - needle->length;
        uint64_t i = 0;
        while (i <= last) {
            if (memcmp(self->data + i, needle->data, needle->length) == 0) {
                matches++;
                i += needle->length;
                if (once) break;
            } else {
                i++;
            }
        }
    }
    uint64_t delta_per =
        (repl->length > needle->length)
            ? (repl->length - needle->length)
            : 0;
    uint64_t shrink_per =
        (needle->length > repl->length)
            ? (needle->length - repl->length)
            : 0;
    uint64_t out_len = self->length + matches * delta_per - matches * shrink_per;
    z_t75_t z = {0};
    z.size = out_len;
    z.capacity = out_len + 1;
    z.data = (char*)z_xmalloc(z.capacity + 1);
    /* pass 2: copy with replacement */
    uint64_t src_i = 0, dst_i = 0, done_matches = 0;
    while (src_i < self->length) {
        bool can_match = (done_matches < matches)
                      && (src_i + needle->length <= self->length)
                      && (memcmp(self->data + src_i, needle->data, needle->length) == 0);
        if (can_match) {
            memcpy(z.data + dst_i, repl->data, repl->length);
            dst_i += repl->length;
            src_i += needle->length;
            done_matches++;
        } else {
            z.data[dst_i++] = self->data[src_i++];
        }
    }
    z.data[dst_i] = '\0';
    return z;
}

static z_t75_t z_t106_replace(
    const z_t106_t* self, const z_t106_t* needle,
    const z_t106_t* replacement);
static z_t75_t z_t106_replace(
    const z_t106_t* self, const z_t106_t* needle,
    const z_t106_t* replacement) {
    return z_t106_replace_impl(self, needle, replacement, false);
}

static z_t75_t z_t106_concat(
    const z_t106_t* self, const z_t106_t* other);
static z_t75_t z_t106_concat(
    const z_t106_t* self, const z_t106_t* other) {
    z_t75_t z = {0};
    uint64_t total = self->length + other->length;
    z.size = total;
    z.capacity = total + 1;
    z.data = (char*)z_xmalloc(z.capacity + 1);
    memcpy(z.data, self->data, self->length);
    memcpy(z.data + self->length, other->data, other->length);
    z.data[total] = '\0';
    return z;
}

static z_t128_t z_t106_indexOf(const z_t106_t* self, const z_t106_t* needle);
static z_t128_t z_t106_indexOf(const z_t106_t* self, const z_t106_t* needle) {
    z_t128_t out = {0};
    uint64_t r = z_t106_indexOf_raw(self, needle);
    if (r == UINT64_MAX) {
        out.tag = Z_OPTIONVAL_U64_TAG_NONE;
        return out;
    }
    out.tag = Z_OPTIONVAL_U64_TAG_SOME;
    out.data.some = r;
    return out;
}


static z_t128_t z_t106_lastIndexOf(const z_t106_t* self, const z_t106_t* needle);
static z_t128_t z_t106_lastIndexOf(const z_t106_t* self, const z_t106_t* needle) {
    z_t128_t out = {0};
    if (needle->length == 0) {
        out.tag = Z_OPTIONVAL_U64_TAG_SOME;
        out.data.some = self->length;
        return out;
    }
    if (needle->length > self->length) {
        out.tag = Z_OPTIONVAL_U64_TAG_NONE;
        return out;
    }
    for (uint64_t i = self->length - needle->length + 1; i > 0; i--) {
        uint64_t idx = i - 1;
        if (memcmp(self->data + idx, needle->data, needle->length) == 0) {
            out.tag = Z_OPTIONVAL_U64_TAG_SOME;
            out.data.some = idx;
            return out;
        }
    }
    out.tag = Z_OPTIONVAL_U64_TAG_NONE;
    return out;
}


static z_t836_t z_t106_byteAt(const z_t106_t* self, uint64_t i);
static z_t836_t z_t106_byteAt(const z_t106_t* self, uint64_t i) {
    z_t836_t out = {0};
    if (i >= self->length) {
        out.tag = Z_OPTIONVAL_U8_TAG_NONE;
        return out;
    }
    out.tag = Z_OPTIONVAL_U8_TAG_SOME;
    out.data.some = (uint8_t)self->data[i];
    return out;
}


static z_t846_t z_t106_stripPrefix(
    const z_t106_t* self, const z_t106_t* p);
static z_t846_t z_t106_stripPrefix(
    const z_t106_t* self, const z_t106_t* p) {
    z_t846_t out = {0};
    if (p->length > self->length
        || (p->length > 0 && memcmp(self->data, p->data, p->length) != 0)) {
        out.tag = Z_OPTION_STRINGVIEW_TAG_NONE;
        return out;
    }
    z_t106_t* boxed = (z_t106_t*)z_xmalloc(sizeof(z_t106_t));
    boxed->data = self->data + p->length;
    boxed->length = self->length - p->length;
    out.tag = Z_OPTION_STRINGVIEW_TAG_SOME;
    out.data = boxed;
    return out;
}


static z_t874_t z_t106_parseI64(const z_t106_t* self);
static z_t874_t z_t106_parseI64(const z_t106_t* self) {
    z_t874_t out = {0};
    uint64_t i = 0;
    int neg = 0;
    if (self->length == 0) goto empty;
    if (self->data[i] == '+' || self->data[i] == '-') {
        if (self->data[i] == '-') neg = 1;
        i++;
    }
    if (i >= self->length) goto empty;
    uint64_t acc = 0;
    for (; i < self->length; i++) {
        unsigned char c = (unsigned char)self->data[i];
        if (c < '0' || c > '9') goto invalid;
        uint64_t d = (uint64_t)(c - '0');
        if (acc > (UINT64_MAX - d) / 10) goto overflow;
        acc = acc * 10 + d;
    }
    /* range check: fits in i64 */
    uint64_t bound = neg ? (uint64_t)1 << 63 : ((uint64_t)1 << 63) - 1;
    if (acc > bound) goto overflow;
    int64_t v = neg ? -(int64_t)acc : (int64_t)acc;
    if (neg && acc == ((uint64_t)1 << 63)) v = INT64_MIN;
    out.tag = Z_RESULTVAL_I64_PARSEERROR_TAG_OK;
    out.data.ok = v;
    return out;
empty:
    out.tag = Z_RESULTVAL_I64_PARSEERROR_TAG_ERR;
    out.data.err.tag = Z_PARSEERROR_TAG_EMPTY;
    return out;
invalid:
    out.tag = Z_RESULTVAL_I64_PARSEERROR_TAG_ERR;
    out.data.err.tag = Z_PARSEERROR_TAG_INVALIDDIGIT;
    return out;
overflow:
    out.tag = Z_RESULTVAL_I64_PARSEERROR_TAG_ERR;
    out.data.err.tag = Z_PARSEERROR_TAG_OVERFLOW;
    return out;
}


static z_t881_t z_t106_parseU64(const z_t106_t* self);
static z_t881_t z_t106_parseU64(const z_t106_t* self) {
    z_t881_t out = {0};
    if (self->length == 0) {
        out.tag = Z_RESULTVAL_U64_PARSEERROR_TAG_ERR;
        out.data.err.tag = Z_PARSEERROR_TAG_EMPTY;
        return out;
    }
    uint64_t acc = 0;
    for (uint64_t i = 0; i < self->length; i++) {
        unsigned char c = (unsigned char)self->data[i];
        if (c < '0' || c > '9') {
            out.tag = Z_RESULTVAL_U64_PARSEERROR_TAG_ERR;
            out.data.err.tag = Z_PARSEERROR_TAG_INVALIDDIGIT;
            return out;
        }
        uint64_t d = (uint64_t)(c - '0');
        if (acc > (UINT64_MAX - d) / 10) {
            out.tag = Z_RESULTVAL_U64_PARSEERROR_TAG_ERR;
            out.data.err.tag = Z_PARSEERROR_TAG_OVERFLOW;
            return out;
        }
        acc = acc * 10 + d;
    }
    out.tag = Z_RESULTVAL_U64_PARSEERROR_TAG_OK;
    out.data.ok = acc;
    return out;
}


static z_t888_t z_t106_parseF64(const z_t106_t* self);
static z_t888_t z_t106_parseF64(const z_t106_t* self) {
    z_t888_t out = {0};
    if (self->length == 0) {
        out.tag = Z_RESULTVAL_F64_PARSEERROR_TAG_ERR;
        out.data.err.tag = Z_PARSEERROR_TAG_EMPTY;
        return out;
    }
    /* copy into a NUL-terminated local buffer for strtod */
    char buf[64];
    char* p = (self->length < sizeof(buf)) ? buf
            : (char*)z_xmalloc(self->length + 1);
    memcpy(p, self->data, self->length);
    p[self->length] = '\0';
    char* end = NULL;
    errno = 0;
    double v = strtod(p, &end);
    int err = errno;
    uint64_t consumed = (uint64_t)(end - p);
    if (p != buf) free(p);
    if (consumed == 0) {
        out.tag = Z_RESULTVAL_F64_PARSEERROR_TAG_ERR;
        out.data.err.tag = Z_PARSEERROR_TAG_INVALIDDIGIT;
        return out;
    }
    if (consumed != self->length) {
        out.tag = Z_RESULTVAL_F64_PARSEERROR_TAG_ERR;
        out.data.err.tag = Z_PARSEERROR_TAG_INVALIDDIGIT;
        return out;
    }
    if (err == ERANGE) {
        out.tag = Z_RESULTVAL_F64_PARSEERROR_TAG_ERR;
        out.data.err.tag = Z_PARSEERROR_TAG_OVERFLOW;
        return out;
    }
    out.tag = Z_RESULTVAL_F64_PARSEERROR_TAG_OK;
    out.data.ok = v;
    return out;
}


static char* z_sv_to_cstr(z_t106_t v) {
    char* buf = (char*)z_xmalloc(v.length + 1);
    if (v.length > 0) memcpy(buf, v.data, v.length);
    buf[v.length] = '\0';
    return buf;
}

static z_t1379_t z_io_errno_to_IoError(int e) {
    z_t1379_t r = {0};
    r.data = NULL;
    switch (e) {
        case ENOENT:  r.tag = Z_IOERROR_TAG_NOTFOUND; break;
        case EACCES:
        case EPERM:   r.tag = Z_IOERROR_TAG_PERMISSIONDENIED; break;
        case EINTR:   r.tag = Z_IOERROR_TAG_INTERRUPTED; break;
        case EEXIST:  r.tag = Z_IOERROR_TAG_EXISTS; break;
        case EISDIR:  r.tag = Z_IOERROR_TAG_ISDIR; break;
        case ENOTDIR: r.tag = Z_IOERROR_TAG_NOTDIR; break;
        case ENOSPC:  r.tag = Z_IOERROR_TAG_NOSPACE; break;
        default:      r.tag = Z_IOERROR_TAG_OTHER; break;
    }
    return r;
}


/* shared helper: write all bytes; returns 0 ok, errno on failure. */
static int z_io_write_all(int fd, const char* data, uint64_t size) {
    uint64_t off = 0;
    while (off < size) {
        long n = write(fd, data + off, size - off);
        if (n < 0) {
            if (errno == EINTR) continue;
            return errno;
        }
        off += (uint64_t)n;
    }
    return 0;
}

/* shared helper: path + open flags -> write content -> close.
   path and content are borrowed views; caller retains. */
static z_t3800_t z_io_write_common(
    z_t106_t path, z_t106_t content, int flags
) {
    z_t3800_t result = {0};
    char* path_cstr = z_sv_to_cstr(path);
    int fd = open(path_cstr, flags, 0644);
    free(path_cstr);
    if (fd < 0) {
        int e = errno;
        z_t1379_t* boxed = (z_t1379_t*)z_xmalloc(sizeof(z_t1379_t));
        *boxed = z_io_errno_to_IoError(e);
        result.tag = Z_RESULT_NULL_IOERROR_TAG_ERR;
        result.data = boxed;
        return result;
    }
    int werr = z_io_write_all(fd, content.data, content.length);
    close(fd);
    if (werr != 0) {
        z_t1379_t* boxed = (z_t1379_t*)z_xmalloc(sizeof(z_t1379_t));
        *boxed = z_io_errno_to_IoError(werr);
        result.tag = Z_RESULT_NULL_IOERROR_TAG_ERR;
        result.data = boxed;
        return result;
    }
    result.tag = Z_RESULT_NULL_IOERROR_TAG_OK;
    result.data = NULL;
    return result;
}


static z_t3851_t z_io_u64_ok(uint64_t v);
static z_t3851_t z_io_u64_ok(uint64_t v) {
    z_t3851_t result = {0};
    uint64_t* boxed = (uint64_t*)z_xmalloc(sizeof(uint64_t));
    *boxed = v;
    result.tag = Z_RESULT_U64_IOERROR_TAG_OK;
    result.data = boxed;
    return result;
}

static z_t3851_t z_io_u64_err(int saved_errno);
static z_t3851_t z_io_u64_err(int saved_errno) {
    z_t3851_t result = {0};
    z_t1379_t* boxed = (z_t1379_t*)z_xmalloc(sizeof(z_t1379_t));
    *boxed = z_io_errno_to_IoError(saved_errno);
    result.tag = Z_RESULT_U64_IOERROR_TAG_ERR;
    result.data = boxed;
    return result;
}


static z_t3800_t z_io_wrap_null_Result(int rc, int saved_errno) {
    z_t3800_t result = {0};
    if (rc == 0) {
        result.tag = Z_RESULT_NULL_IOERROR_TAG_OK;
        result.data = NULL;
        return result;
    }
    z_t1379_t* boxed = (z_t1379_t*)z_xmalloc(sizeof(z_t1379_t));
    *boxed = z_io_errno_to_IoError(saved_errno);
    result.tag = Z_RESULT_NULL_IOERROR_TAG_ERR;
    result.data = boxed;
    return result;
}


/* Populate fs from a struct stat. Shared by z_io_stat / z_io_lstat —
   the only behavioral split between them lives in the syscall call
   site (stat(2) follows symlinks, lstat(2) does not). */
static void z_io_fill_filestat(z_t3809_t* fs, const struct stat* sb);
static void z_io_fill_filestat(z_t3809_t* fs, const struct stat* sb) {
    if (S_ISREG(sb->st_mode))       fs->kind.tag = Z_FILEKIND_TAG_FILE;
    else if (S_ISDIR(sb->st_mode))  fs->kind.tag = Z_FILEKIND_TAG_DIR;
    else if (S_ISLNK(sb->st_mode))  fs->kind.tag = Z_FILEKIND_TAG_SYMLINK;
    else                            fs->kind.tag = Z_FILEKIND_TAG_OTHER;
    fs->size = (uint64_t)sb->st_size;
    fs->mtimeSeconds = (uint64_t)sb->st_mtime;
    fs->atimeSeconds = (uint64_t)sb->st_atime;
    fs->ctimeSeconds = (uint64_t)sb->st_ctime;
    fs->mode = (uint32_t)sb->st_mode;
    fs->device = (uint64_t)sb->st_dev;
    fs->inode = (uint64_t)sb->st_ino;
    fs->nlink = (uint64_t)sb->st_nlink;
}


static void z_io_eprintln(z_t106_t sv) {
    fprintf(stderr, "%.*s\n", (int)sv.length, sv.data);
}


static bool z_io_exists(z_t106_t path) {
    char* path_cstr = z_sv_to_cstr(path);
    int r = access(path_cstr, F_OK);
    free(path_cstr);
    return r == 0;
}


static z_t3794_t z_io_readText(z_t106_t path) {
    /* path is a borrowed view; caller retains ownership */
    z_t3794_t result = {0};
    char* path_cstr = z_sv_to_cstr(path);
    int fd = open(path_cstr, O_RDONLY);
    free(path_cstr);
    if (fd < 0) {
        int e = errno;
        z_t1379_t* boxed = (z_t1379_t*)z_xmalloc(sizeof(z_t1379_t));
        *boxed = z_io_errno_to_IoError(e);
        result.tag = Z_RESULT_STRING_IOERROR_TAG_ERR;
        result.data = boxed;
        return result;
    }
    z_t75_t content = z_t75_create((uint64_t)4096);
    char buf[4096];
    for (;;) {
        long n = read(fd, buf, sizeof(buf));
        if (n == 0) break;
        if (n < 0) {
            if (errno == EINTR) continue;
            int e = errno;
            close(fd);
            z_t75_free(&content);
            z_t1379_t* boxed = (z_t1379_t*)z_xmalloc(sizeof(z_t1379_t));
            *boxed = z_io_errno_to_IoError(e);
            result.tag = Z_RESULT_STRING_IOERROR_TAG_ERR;
            result.data = boxed;
            return result;
        }
        z_t75_append(&content, buf, (uint64_t)n);
    }
    close(fd);
    z_t75_t* boxed = (z_t75_t*)z_xmalloc(sizeof(z_t75_t));
    *boxed = content;
    result.tag = Z_RESULT_STRING_IOERROR_TAG_OK;
    result.data = boxed;
    return result;
}


static z_t3800_t z_io_remove(z_t106_t path) {
    char* path_cstr = z_sv_to_cstr(path);
    /* try unlink first; if EISDIR, fall back to rmdir */
    int rc = unlink(path_cstr);
    int e = errno;
    if (rc != 0 && e == EISDIR) {
        rc = rmdir(path_cstr);
        e = errno;
    }
    free(path_cstr);
    return z_io_wrap_null_Result(rc, e);
}


/* stat(2) follows symlinks; the SYMLINK arm never fires here —
   that arm is reached through z_io_lstat. Returns the filestat
   value by value (not boxed); the compiler-generated result
   destructor frees the ok payload's heap copy. */
static z_t3819_t z_io_stat(z_t106_t path);
static z_t3819_t z_io_stat(z_t106_t path) {
    z_t3819_t result = {0};
    char* path_cstr = z_sv_to_cstr(path);
    struct stat sb;
    int rc = stat(path_cstr, &sb);
    int e = errno;
    free(path_cstr);
    if (rc != 0) {
        z_t1379_t* boxed = (z_t1379_t*)z_xmalloc(sizeof(z_t1379_t));
        *boxed = z_io_errno_to_IoError(e);
        result.tag = Z_RESULT_FILESTAT_IOERROR_TAG_ERR;
        result.data = boxed;
        return result;
    }
    z_t3809_t fs = {0};
    z_io_fill_filestat(&fs, &sb);
    z_t3809_t* boxed = (z_t3809_t*)z_xmalloc(sizeof(z_t3809_t));
    *boxed = fs;
    result.tag = Z_RESULT_FILESTAT_IOERROR_TAG_OK;
    result.data = boxed;
    return result;
}


